class TwoMany {
    static void howMany(int k) {
        switch (k) {
            case 1: System.out.println("one");
                break;  // exit the switch
            case 2: System.out.println("two");
                break;  // exit the switch
            case 3: System.out.println("many");
                break;  // not needed, but good style
        }
    }
    static void howManyAgain(int k) {
        switch (k) {
            case 1 -> System.out.println("one");
            case 2 -> System.out.println("two");
            case 3 -> System.out.println("many");
        }
    }
